MG=_v6('V6_MUZZLE_GROW',0.0)   # muzzle volume grows DOWN, top edge fixed (.472+.032=.504); only needed if the lip line moves below the muzzle's reach
# Toes sit AT the front of the paw ball (round E, 2026-09-30). They used to be placed 2cm ahead of
# the paw's centre inside a ball 17.6cm deep - buried, so the foot read as a pom-pom however the
# coat was set. The ball is shorter now (ry .088 -> .072 front, .085 -> .070 rear) and each toe's
# centre is 6mm proud of its front surface.
PAW_FRONT_Y={'Front':-.215-PAW['Front'][1][1],'Rear':.245-PAW['Rear'][1][1]}
# Round G (review b4 + round F audit): F's toes sat in one straight row 3mm AHEAD of the ball -
# 25-33mm proud, and 42mm wide at 22mm spacing, so neighbours overlapped by 20mm and no cleft
# showed: four cotton balls glued on the front. Now each toe sits ON the paw ellipsoid where it
# is (the outer toes follow the round front back ~16mm), TOE_IN inside it, so the front edge
# stands ~12mm proud; narrower toes at 24mm spacing leave a ~6mm-deep cleft between them.
PAD_C={(pre,s):(s*x,y-.026) for pre,y,x in (('Front',-.17,.108),('Rear',.26,.12)) for s in (-1,1)}   # main pad centres (x, y), as the pads are built below   # == the FrontPaw/RearPaw spheres above
# Round G2: G's toes read as four small pom-poms along the bottom edge (36mm tall on a 78mm paw);
# the reference's toes ARE the front half of the paw - taller now (42mm). And the outer toes follow
# the round front only 60% of the way: at 16mm back, WorkBuddy measured no cleft on the outer pairs.
# Round I (user: "the paws are wrong" - four white balls): G2's toes stood 16-20 mm proud, and the
# outer pair, pulled back 9 mm along the arc, only STEPPED back from the inner toes: measured, those
# two clefts were -3.8 mm (no groove; v6_part_audit cleft_depth_sym). In the reference the four toes
# ARE the front of a mitten - each lobe ~60% of the paw's height, pressed together along dark creases.
# (Small flat toes at the bottom were tried first - round-i-test s1: a bald ball on four beads.)
# Now the lobes keep G2's height, sit 4 mm deeper and lean on a gentler arc (outer toes ~2 mm back):
# every cleft is a groove behind both of its crowns. 22 mm apart on 32 mm toes (10 mm overlap): pressed
# together, the clefts are lines, not the gaps between four eggs (24 mm, round-i-test s2).
TOE_DX=_v6('V6_TOE_DX',.019)*PAW_SC;TOE_R=(.016*_v6('V6_TOE_W',.80)*PAW_SC,.020*_v6('V6_TOE_L',.64)*PAW_SC,.022*_v6('V6_TOE_H',.56));TOE_Z=.001+TOE_R[2];TOE_IN=.012*_v6('V6_TOE_IN',2.0);TOE_ARC=_v6('V6_TOE_ARC',.04)
# Round P (user: 「爪子的指头有点大，爪子的肉垫有点小」): smaller again, .90/.70/.62 -> .80/.64/.56 (26 x 23 x 25 mm), the beans
# on them larger (BEAN_S) and the main pad x1.4 (PAD_S).
# Round O (user: 「脚趾太大了，其实脚趾的骨骼比较小，就是猫毛多一些」): the toe bones are small - 22 x 28 x 27 mm, 21 mm
# apart, 5 mm proud of the ball - and the paw's rounded front is its coat; the creases stay as shading. (Round N below.)
# round N (codex paw refs lingxi-ref-paw-front/-side): the four toes ARE the front of the foot - creases .29 of the
# foot's width apart, lobes .40 of it tall. Was 22 mm apart on a 98 mm row under a 108 mm, 78 mm tall paw ball: four
# beads under a club. Now 27 mm apart (row 115 mm = the ball), 34 x 42 mm, 7 mm deeper forward, ball 24 mm lower
# (V6_PAW_LOW), outer toes barely back: clefts 1.4/3.4 -> 4.5/5.3 mm (v6_part_audit toe_clefts, sym).
# round L: .82 high (44 -> 36 mm), bottoms where they were - taller than wide they read as four fingers; the reference's toes are low round bumps (round-l-test t3/t4)
def toe_xy(pre,s,i):
 (cx,cy,cz),(rx,ry,rz)=PAW[pre];dx=(i-1.5)*TOE_DX;h=((TOE_Z-cz)/rz)**2
 yc=cy-ry*math.sqrt(max(1-h,.05));yi=cy-ry*math.sqrt(max(1-(dx/rx)**2-h,.05))
 return s*cx+dx,yc+TOE_ARC*(yi-yc)+TOE_IN
if PAW_META:   # round R: the toes, pads and front line of the metaball paw
 PAW_FRONT_Y={k:m['front'] for k,m in MPAW.items()};TOE_R,TOE_DX,TOE_Z,TOE_ARC=MTOE_R,MTOE_DX,MTOE_Z,MTOE_ARC;toe_xy=mtoe_xy
 PAD_C={(pre,s):(s*m['x'],m['padc']) for pre,m in MPAW.items() for s in (-1,1)}
CK_RX,CK_RZ=_v6('V6_CHEEK_RX',.070),_v6('V6_CHEEK_RZ',.064)   # round N (「脸是不是胖了」): the cheek lobes' width and depth, top edge fixed (.530)
head=merge([sphere('Cranium',(0,-.285,.518),(.165,.147,.142)),sphere('CheekL',(-.095,-.340,.530-CK_RZ),(CK_RX,.082,CK_RZ)),sphere('CheekR',(.095,-.340,.530-CK_RZ),(CK_RX,.082,CK_RZ)),sphere('MuzzleL',(-.031,-.408,.472-MG),(.052,.047,.032+MG)),sphere('MuzzleR',(.031,-.408,.472-MG),(.052,.047,.032+MG))],'LX_Head',.005)
head.data.materials.clear();head.data.materials.append(headcoat)
# --- Head sculpt ---------------------------------------------------------------------------------
# The skull was a union of ellipsoids: every feature a kitten's face has in relief - brow over
# the eye, the dip of the stop between the eyes, the round whisker pads, the full lower cheeks, a
# small chin - was missing, so fur lay on a ball. These brushes push the skin along its normal
# (metres; + is outward), sized from the face close-up reference.
SCULPT=[((0,-.418,.528),.022,-.0045*_v6('V6_STOP_K',2.0)),                                  # stop: the dip between the eyes
        ((0,-.395,.575),.030,+.0030*_v6('V6_FOREHEAD_K',1.0)),                                  # forehead dome above it
        # Final check (head profile flat - codex ROUND-ZM-AUDIT 4, lingxi-ref-head-profile: the brow recedes from the nose, a stop between):
        # the forehead's midline set back above the stop (V6_BROW_BACK m; 0 = off)
        ((0,-.405,.585),.032,-_v6('V6_BROW_BACK',0.0)),
        ((-.060,-.395,.570),.020,+.0035*_v6('V6_BROW_K',1.6)),((.060,-.395,.570),.020,+.0035*_v6('V6_BROW_K',1.6)),   # brow over each eye
        # ZK: the brow ridge over the eye's outer half and a zygomatic lift under its outer corner - the frame a sunken eye sits in
        ((-.086,-.396,.575),.020,+.0045*_v6('V6_BROW_K',1.6)),((.086,-.396,.575),.020,+.0045*_v6('V6_BROW_K',1.6)),
        ((-.090,-.415,.486),.018,+.0040*_v6('V6_ZYG_K',1.0)),((.090,-.415,.486),.018,+.0040*_v6('V6_ZYG_K',1.0)),
        ((-.026,-.448,.463),.018,+.0050),((.026,-.448,.463),.018,+.0050),   # whisker pads
        ((-.105,-.355,.455),.040,+.0070),((.105,-.355,.455),.040,+.0070),   # full lower cheeks
        ((0,-.430,.428),.020,+.0030*_v6('V6_CHIN_K',-1.0)),
        # the skin behind a nose moved forward (V6_NOSE_FWD) and a short bridge up to it, so it stays seated on the face
        ((0,-.448,.487),.016,+.90*_v6('V6_NOSE_FWD',.015)),((0,-.443,.505),.014,+.45*_v6('V6_NOSE_FWD',.015)),                                  # chin (V6_CHIN_K < 0 sets it back - codex head_side_target: the chin's coat 13-18 mm behind ours)
        ((0,-.26,.66),.080,-.0060)]                                    # a lower, flatter crown
def sculpt(o):
 me=o.data;me.update();bpy.context.view_layer.update();mw=o.matrix_world.copy()   # merged mesh: local != world
 for v in me.vertices:
  d=0.0;p=mw@v.co
  for c,rad,amt in SCULPT:d+=amt*math.exp(-((p.x-c[0])**2+(p.y-c[1])**2+(p.z-c[2])**2)/rad**2)
  if d:v.co=v.co+v.normal*d      # displace the LOCAL coordinate; p (world) only locates the brush
 me.update()
sculpt(head)
# Eye placement, shared by the Eye bones, the lens, the lids and the groom's eye window.
# Eyelids are spherical shells around a centre far behind the eye, rotated shut by their own bones
# (see "Face rig" below). LID_APEX is how far the lid stands in front of the cornea's plane.
LID_APEX=_v6('V6_LID_APEX',.010)   # rig v2 eye volume: 4.8 -> 10 mm proud (lid sphere 172 -> ~86 mm): the eye a lens, not a disc   # .0040 left the lower lid's corner (with its 2mm shell) coincident with the cornea
EYE_X=.064*_v6('V6_EYE_X',1.20);EYE_Z=.523*_v6('V6_EYE_Z',1.0);EYE_R=.038*_v6('V6_EYE_R',1.06)   # round L (user approved): x1.20 apart, .95 -> 1.06 across - the reference's eyes sit .38 of the furred head apart and are .17 of it across; ours were .30 / .15, a crowded little face (round-l-test f1-f3).
#   # .95 (2026-09-29, v6_eye_size.py): at 1.0 the outer iris measured .48E bald-rimmed and .55E once the eyeliner rim widened, against the reference's .50E; .95 splits it. The earlier .66 was a MEASUREMENT error - v6_face_shape.py sized pupils by their largest inscribed circle, which the reference's big catchlights bite into (.194E where the hole-filled pupil is .34E); at .66 the eyes were a third too small, beads instead of the reference's big round eyes
EAR_S=_v6('V6_EAR',1.0)   # ear shell scaled about its base; the Ear bones scale with it (.82 = v6's smaller ear, tried 2026-09-30; the user preferred 1.0)
LID_YC=(EYE_R**2-LID_APEX**2)/(2*LID_APEX);LID_R=LID_YC+LID_APEX   # sphere through the eye's rim, LID_APEX proud at its centre
LIP0=.4575*_v6('V6_LIP',1.0)      # lip-line centre: 16mm under the nose leather (24mm read as a long, sad philtrum)
LIP_DZ=LIP0-.4575   # the mouth assembly MUST ride with the lip line - cavity/floor/tongue/teeth/jaw - or pink skin peeks above the new lip (v6 lesson)
MOUTH_W=.024*_v6('V6_MOUTH_W',1.0);MW_K=MOUTH_W/.024;MW2=.016*_v6('V6_LOWER_LIP_W',.66)   # round R: the pink lower lip keeps its old .011 half-width when the omega widens (V6_MOUTH_W 1.0) - wide, it read as a pink wavy band under the mouth   # half-width of the mouth: about the nose's width, as in the references (was .046, .036)
LIP_SAG=.0035*_v6('V6_LIP_SAG',1.0)   # how far each upper-lip arc dips below the cusp (round G; negative = the old "m"). Round ZZP (user: 「codex 的图是两边是向下的感觉」 - checked on face-closeup / mouth-closed / face-q34: the line runs down and out along the whisker pads' bottoms, a "人", with the pink lower lip in the notch; ZZO's turned-up corners were the wrong way): back to 1.0, no corner rise; what read as a frown was the DARK wedge in the notch - the lower lip now fills it (V6_LOWER_LIP_DZ / _BEVEL)
GAPE_W=.036*_v6('V6_GAPE_W',.85)   # round R: 1.45 -> 1.0 with the arched lip and a deeper jaw - the yawn rounds into the reference's U instead of a wide box (round-r-test mo0-mo3)
#   # round L: 1.2 - the yawn's corners open to ~70 mm; past 1.2 the cut does not get wider (round-l-test y3)
#    # half-width of the actual cut: closed at rest (so the drawn omega stays small), but a
               # yawn opens the corners back to here - a cat's gape runs well past its visible lips
def lip_z(x):
 """Height of the upper-lip line at x: the two arcs of the omega meeting under the philtrum,
  rising at the corners. The mouth opens along this line."""
 u=np.minimum(np.abs(x)/MOUTH_W,1)
 # Round G: the arcs SAG from the philtrum cusp, like the bottoms of the two whisker pads (the
 # reference's "omega", with the lower lip's pink showing in the notch under the cusp). They used
 # to bulge UP from it, which drew an "m" - read on the render as a flat wavy pink line.
 return LIP0-LIP_SAG*np.sin(np.pi*np.minimum(u/.78,1))+_v6('V6_LIP_CORNER',0.0)*np.maximum(0,u-.78)/.22   # round ZZO: the corner's rise a knob
def jaw_share(x,y,z,below):
 """How much of a head point the jaw carries: the lip, whisker-pad bottoms and chin in front,
  fading out toward the throat and the mouth corners so the skin there stretches, not tears."""
 # The chin only: the whisker pads belong to the UPPER jaw. Giving their lower halves to the jaw bone
 # (width .056) tore the skin between them vertically on every open mouth - white bars beside the nose.
 wmax=GAPE_W+.8*np.clip(LIP0-.004-z,0,.05)            # the lower lip out to the gape corners, the full chin lower down
