# Every eye-placed thing (bones, lens, lids, lid weights, the groom's eye window) goes through eye_y.
EYE_SINK=_v6('V6_EYE_SINK',.007)   # ZL: 5 -> 7 mm (5 mm: set in a little, still proud in 3/4)
