# Weight algorithm: piecewise smooth anatomical regions, normalized per vertex.
def _bseg(name):
 b=ad.bones[name];return np.array(b.head_local[:]),np.array(b.tail_local[:])
def _segd(p,a,b):
 ab=b-a;t=np.clip(((p-a)@ab)/(ab@ab),0,1);return np.linalg.norm(p-(a+t[:,None]*ab),axis=1)
def face_fields(P,below=None,only=None):
 """Rig v1: the face control bones' weights at points P (authored space) - a soft gaussian round each control, the brows kept
  off the eye's rim (so a raised brow does not drag the lid over the eye), the upper lip's sides only above the lip line and the
  lower lip only below it (`below`: 1 under the line), all of it only on the front of the face. Summed at most .95."""
 if not FACE_V1:return {}
 x,y,z=P[:,0],P[:,1],P[:,2]
 if below is None:below=(z<lip_z(x)-.0005).astype(float)
 G=lambda cx,cz,rx,rz:np.exp(-((x-cx)/rx)**2-((z-cz)/rz)**2);fr=lambda y0:np.clip((y0-y)/.03,0,1);out={}
 for s_,sf in ((-1,'L'),(1,'R')):
  eg=np.clip((np.hypot(x-s_*EYE_X,z-EYE_Z)-1.05*EYE_R)/(.25*EYE_R),0,1)
  for nm in ('BrowIn.','BrowOut.'):bx,bz,_=FACE_BONES[nm+sf];out[nm+sf]=G(bx,bz,.014,.012)*fr(-.30)*eg
  if only!='brow':
   bx,bz,_=FACE_BONES['MouthCorner.'+sf];out['MouthCorner.'+sf]=G(bx,bz,_v6('V6_CORNER_RX',.020),.010)*fr(-.37)   # round Z: .013 -> .020 wide - the corner alone moved under the whisker pads' fur; now the omega's arcs bend with it
   bx,bz,_=FACE_BONES['LipUp.'+sf];out['LipUp.'+sf]=G(bx,bz,.014,.009)*fr(-.37)*(1-below)
   bx,bz,_=FACE_BONES['NoseSide.'+sf];out['NoseSide.'+sf]=G(bx,bz,.012,.010)*fr(-.40)
   bx,bz,_=FACE_BONES['Nostril.'+sf];out['Nostril.'+sf]=G(bx,bz,.008,.006)*fr(-.40)
 if only!='brow':bx,bz,_=FACE_BONES['LipLow'];out['LipLow']=G(bx,bz,.018,.009)*fr(-.37)*below
 if FACE_V2 and only!='brow':
  # rig v2 sheets: full weight inside r0, smoothstep to 0 at r1 (ax / az stretch the ellipse); own side of the midline only for the
  # paired ones; the upper-lip sheet and the pads above the lip line; the orbit and cheek kept off the eye itself
  def S(cx,cz,r0,r1,ax=1.,az=1.):
   d=np.hypot((x-cx)/ax,(z-cz)/az);t=np.clip((r1-d)/(r1-r0),0,1);return t*t*(3-2*t)
  for s_,sf in ((-1,'L'),(1,'R')):
   side=np.clip((s_*x-.002)/.006,0,1);eye=np.clip((np.hypot(x-s_*EYE_X,z-EYE_Z)-1.08*EYE_R)/(.18*EYE_R),0,1)
   bx,bz,_=FACE_BONES['MuzzlePad.'+sf];out['MuzzlePad.'+sf]=S(bx,bz,.018,.042,1.,.8)*fr(-.36)*side*(1-below)
   bx,bz,_=FACE_BONES['UpperLipSheet.'+sf];out['UpperLipSheet.'+sf]=S(bx,bz,.009,.027,1.,.8)*fr(-.38)*side*(1-below)
   bx,bz,_=FACE_BONES['CheekLift.'+sf];out['CheekLift.'+sf]=S(bx,bz,.018,.050,1.,.8)*fr(-.30)*eye
   bx,bz,_=FACE_BONES['OrbitLower.'+sf];out['OrbitLower.'+sf]=S(bx,bz,.009,.028,1.6,.7)*fr(-.33)*eye
  bx,bz,_=FACE_BONES['NoseBridge'];out['NoseBridge']=S(bx,bz,.006,.019)*fr(-.40)
 tot=sum(out.values());k=np.where(tot>.95,.95/np.maximum(tot,1e-9),1.0)
 return {nm:v*k for nm,v in out.items() if v.max()>1e-4}
def _with_face(w,P,below=None,only=None):
 fw=face_fields(P,below,only)
 if not fw:return w
 # Round Z2: each control takes its share from its own side of the mouth - LipLow (a child of Jaw) from the jaw's weight, the others
 # (children of Head) from the rest. Taken from both, the corner fields put .5-.9 of the lower lip's inner skin on the head and an
 # open mouth stretched it across the gap as a pale curtain over the cavity - every yawn, meow, hiss and lick since rig v1.
 w={k:np.asarray(v,dtype=float) for k,v in w.items()};isj=lambda k:k in ('Jaw','LipLow') or k.startswith('Tongue')
 for jaw_side in (False,True):
  side={k:v for k,v in fw.items() if (k=='LipLow')==jaw_side};src=[k for k in w if isj(k)==jaw_side]
  if not side or not src:continue
  share=sum(w[k] for k in src);tot=sum(side.values())
