def weights(points,region):
 if FACE_V1 and not region.endswith('#') and (region in ('Head','Lip','Nose','JawSkin') or region.startswith('Lid:')):
  # rig v1: the face control bones take their share of the skin (and of the coat rooted on it)
  base=weights(points,'Jaw' if region=='JawSkin' else region+'#')
  return _with_face(base,points,np.ones(len(points)) if region=='JawSkin' else None,'brow' if region.startswith('Lid:') else None)
 region=region[:-1] if region.endswith('#') else region
 n=len(points);w={}
 def add(k,v):w[k]=np.asarray(v if np.ndim(v) else np.full(n,v),dtype=float)
 if region.startswith('Lid:'):
  # Lid bone weight: full on the lid's inner half, fading to the head at its outer edge, and less
  # toward the corners (canthi), which a real lid does not move.
  _,ul,sf=region.split(':');sg=-1 if sf=='L' else 1;phi=sg*math.radians(12)
  cx=sg*EYE_X;ys=eye_y(cx);x,y,z=points.T
  lx=(x-cx)*math.cos(phi)+(y-ys)*math.sin(phi);lz=z-EYE_Z
  rho=np.hypot(lx,lz)/EYE_R;base,span=(.93,.37) if ul=='U' else (.97,.33)
  t=np.clip((rho-base)/span,0,1);sa=np.abs(lz)/np.maximum(np.hypot(lx,lz),1e-9)
  wl=np.clip(1.6*(1-t),0,1)*(.25+.75*sa**.6)
  add(('LidUpper.' if ul=='U' else 'LidLower.')+sf,wl);add('Head',1-wl);return w
 if region=='HeadRigid':           # upper teeth: never split between head and jaw
  add('Head',1);return w
 if region=='Lip':                 # the drawn upper lip: never on the jaw, but lifted with the lip skin
  x,y,z=points.T;l=lip_share(x,y,z,1.0);add('Head',1-l);add('LipUpper',l);return w
 if region=='Cavity':
  # Round J: the mouth bag opens with the jaw - its floor goes down with the chin, its roof stays - so a
  # wide gape never shows the white inside of the head shell between the bag and the lips.
  j=np.clip((CAV_Z-points[:,2])/.012,0,1);add('Head',1-j);add('Jaw',j);return w
 if region=='Head':
  x,y,z=points.T;b=(z<lip_z(x)-.0005).astype(float);j=jaw_share(x,y,z,b);l=lip_share(x,y,z,1-b)
  add('Head',1-j-l)
  if (j>0).any():add('Jaw',j)
  if (l>0).any():add('LipUpper',l)
  return w
 if region.startswith('Ear:'):
  # rig v1: from the ear's root to its tip bone over its middle (codex EAD103 / 106: the ear bends as it flattens or lies back)
  sf=region[4:];h=np.array(ad.bones['Ear.'+sf].head_local[:]);t=np.array(ad.bones['EarTip.'+sf].tail_local[:]);d=t-h
  tt=np.clip(((points-h)@d)/(d@d),0,1);wt=np.clip((tt-.30)/.45,0,1);wt=wt*wt*(3-2*wt);add('EarTip.'+sf,wt);add('Ear.'+sf,1-wt);return w
 if region=='TongueChain':
  tb=['Tongue','TongueMid','TongueTip'];mid=np.array([(ad.bones[k].head_local.y+ad.bones[k].tail_local.y)/2 for k in tb])
  H=np.array([np.interp(-points[:,1],-mid,np.eye(3)[i]) for i in range(3)])
  for i,k in enumerate(tb):add(k,H[i])
  return w
 if region not in ['body','tail']:
  add(region,1);return w
 if region=='tail':
  if RIG_X:
   # round X: by where along the tail a point lies (its nearest point on the bone chain), each joint blended over a bone length
   tb=[b.name for b in ad.bones if b.name.startswith('Tail')];tb.sort(key=lambda n:ad.bones[n].head_local.y)
