# Closing the lids (2026-10-01): each lid turns shut about its own sphere's centre PER VERTEX, in
# its Blink key. The inner rim turns all the way (upper .81 eye-radii down, lower 1.13 up - the
# travel the lid bones had), the corners (sin=0) and the outer edge (t=1) stay put, and the band
# between shares the turn by arc length. The bones did it with one rigid turn blended by skin
# weights: a blended turn is a chord, so a partly-weighted lid sank up to 1.2mm inside its sphere,
# and with the corners only damped to 25% the upper rim fell .2r below them while the lower rose
# .28r above - the crossed lids and the smooth plate the user read as an eye mask (round b4b).
# ZL (user: 「闭眼的时候有眼痕」; lingxi-ref-face-eyes-a closed: the shut line arches UP across the eye and hooks down into the inner corner):
# V6_SHUT_ARCH more travel for both lids raises the arch from .12 r to .12+k r; the almond's low nasal corner gives the hook
_SA=_v6('V6_SHUT_ARCH',.10)
LID_SHUT={'U':.81-_SA,'L':1.13+_SA}                # inner-rim travel when shut, in eye radii
LID_RING={'U':(.93,.37),'L':(.97,.33)}     # inner-rim radius and band width, in eye radii (the lid mesh below)
# The dark margin (t<.2, see "lid colour") turns with the rim as one piece: spread by arc length
# it would stretch with the band (x3.2) into a 7mm dark stripe across the closed eye.
LID_MARGIN=.20*_v6('V6_LID_MARGIN',1.0)
# Rig v1 lid keys, the same exact turn at other fractions: Wide opens the upper lid past rest (codex AU5, the startled / wide eye),
# Lift raises the lower lid (soft / squinting), and Smile pairs an upper lid .80 shut with a lower lid pushed past the meeting
# line (1.25): it tucks behind the upper, and the closed eye is the upper rim's higher arch - the ^ ^ eye.
# Round ZD (codex ROUND-Z-REMEASURE 5: the happy eye's closed line arched .04 of the eye's width, target .12): the Smile keys turn each
# point by its own fraction - the upper lid less and the lower one further toward the middle of the eye - so where they meet it is
# an arch up (^ ^), not the flat line of a blink. V6_SMILE_ARCH 0 gives the old uniform .80 / 1.25.
SMILE_ARCH=_v6('V6_SMILE_ARCH',.15)   # ZF: .5 -> .7 (codex ROUND-ZD-AUDIT 5: the arch still .04-.06 short under the lid coat)
def _lid_sin(P,s):L=lid_local(P,s);return np.abs(L[:,2])/np.maximum(np.hypot(L[:,0],L[:,2]),1e-9)
# Round ZZM (audit A4: the happy eye shut as a pale round dome - the upper lid only .80 shut, the lower lid pushed past the line to 1.25
# filled the eye with its pale coat and hid the arch under the upper lid's coat; the plain blink, both lids meeting, reads as a clean dark
# line): V6_SMILE_U / _L set the two lids' base fractions; the arch (SMILE_ARCH) is kept on top. .80 / 1.25 -> .92 / 1.08 (round-zzl-test
# sm1): the arch line moves to the middle of the eye and reads; the eye's round bulge stays. Round ZZN: the bulge was the LOWER lid's pale coat -
# the arch is made by pushing the lower lid past the meeting line in the middle (arch .70: to 1.78 of its travel, covering most of the eye).
# A blink-like shut (.99 / 1.00) with a gentle arch .15 gives the clean dark line of 闭眼休息 bowed up a little, no pale dome (zzm-test a15;
# a30 / a45 still domed). codex's target arch is a little higher; the clean line reads better than a higher arch over a pale dome.
LID_V1={'U':(('Wide',-.25),('Smile',lambda P,s:_v6('V6_SMILE_U',.99)-.6*SMILE_ARCH*_lid_sin(P,s)**1.5)),'L':(('Lift',.45),('Smile',lambda P,s:_v6('V6_SMILE_L',1.00)+SMILE_ARCH*_lid_sin(P,s)**1.5))}
def _lid_slants(P,s):
 """Round Z (user: 「表情不对，所有表情都一样」): the upper lid shut more on one side - SlantIn lowers its inner half (the frown of
  an angry / intent cat), SlantOut its outer half (the droop of a sad one). Per-point fractions of the same exact turn; the brow
  layer reads through these - a cat's brow is fur, and moving it barely showed."""
 L=lid_local(P,s);a=np.arctan2(L[:,2],L[:,0]);win=np.clip((1-s*np.cos(a))/2,0,1)
 # the whole lid comes down, more on one side (round Z2: weighted to the corners only, mean 2.6 mm against the blink's 10.7, the lid
 # never reached the iris - the open eye's lid sits above it - and furrow / sad rendered as the neutral face)
 # Z3: x1.6 - at .08 -> .58 of a blink across the eye the fur-covered lid took ~.1 off the iris's inner top (target furrow: slope +.18 iris)
 return (('SlantIn',.12+.80*win**1.3),('SlantOut',.12+.70*(1-win)**1.3))
def lid_local(P,s):
 """World points (N,3) to the eye-local frame of eye_frame(): x across, y into the head, z up."""
 cx=s*EYE_X;ys=eye_y(cx);phi=s*math.radians(12);c,sn=math.cos(phi),math.sin(phi)
 x=P[:,0]-cx;y=P[:,1]-ys
 return np.column_stack((x*c+y*sn,-x*sn+y*c,P[:,2]-EYE_Z))
def lid_world(L,s):
 cx=s*EYE_X;ys=eye_y(cx);phi=s*math.radians(12);c,sn=math.cos(phi),math.sin(phi)
 return np.column_stack((cx+L[:,0]*c-L[:,1]*sn,ys+L[:,0]*sn+L[:,1]*c,L[:,2]+EYE_Z))
def lid_base(a,ul,s):
 """Inner-rim radius of a lid (eye radii) at angle a. Rig v2 eye (codex ROUND-ZH-AUDIT 1, eye_outline_template.png): an almond -
  the opening runs out to a small point at the nasal corner, a little below the horizontal (the caruncle sits in it), and the upper
  lid's middle comes down a touch; the old opening was the same circle as the iris. V6_EYE_ALMOND 0 = the circle."""
 base=LID_RING[ul][0]
 if _v6('V6_EYE_ALMOND',2.0)<=0 or not FACE_V2:return base+0*np.asarray(a,dtype=float)
 an=0.0 if s<0 else math.pi;ac=an+(-1 if s<0 else 1)*math.radians(_v6('V6_CANTHUS_DROP',15))
 g=np.clip(np.cos(np.asarray(a,dtype=float)-ac),0,1)**6
 k=_v6('V6_EYE_ALMOND',2.0);ext=(.09 if ul=='U' else .05)*k;top=(.025*k*np.sin(a)**2) if ul=='U' else 0.0
 return base+ext*g-top
def lid_turn_angle(L,ul,s=None):
 """Angle (+ = down) about the lid sphere's x axis that shuts each eye-local point (N,3).
  The rim lands on .12r*sin(a) (upper) / .16r*|sin(a)| (lower): two arches through the corners,
  the lower one just behind the upper, so the closed eye is the upper rim's arch."""
 base,span=LID_RING[ul];Rl=LID_R+.0008 if ul=='U' else LID_R;r=EYE_R
 a=np.arctan2(L[:,2],L[:,0])
 if s is not None:base=lid_base(a,ul,s)   # rig v2: the almond rim
 rx,rz=np.cos(a)*base*r,np.sin(a)*base*r
 dy=-np.sqrt(np.maximum(Rl*Rl-rx*rx-rz*rz,1e-12));rho=np.hypot(dy,rz)
 tz=rz+(-1 if ul=='U' else 1)*LID_SHUT[ul]*r*np.abs(np.sin(a))
 al=np.arctan2(rz,-dy)-np.arcsin(np.clip(tz/rho,-1,1))
 # arc length along the band is linear in t to 1% (the sphere is 140mm round, the band 13mm wide)
 t=np.clip((np.hypot(L[:,0],L[:,2])/r-base)/span,0,1)
 return al*np.clip(1-(t-LID_MARGIN)/(1-LID_MARGIN),0,1)
def lid_turn(P,s,ul,frac,roots=None):
 """World points P turned shut by `frac` of their angle (an exact turn, so a squint stays on the
  sphere too). Fur strand points pass their ROOTS: a strand turns rigidly with the skin under it."""
 L=lid_local(P,s);A=lid_turn_angle(lid_local(roots,s) if roots is not None else L,ul,s)*frac
 dy=L[:,1]-LID_YC;dz=L[:,2];c,sn=np.cos(A),np.sin(A)
 return lid_world(np.column_stack((L[:,0],LID_YC+dy*c-dz*sn,dy*sn+dz*c)),s)
for s in [-1,1]:
 suf='L' if s<0 else 'R';cx=s*EYE_X;cz=EYE_Z;r=EYE_R;ys=eye_y(cx);cy=ys
 phi=s*math.radians(12)            # turned half-way toward the skull normal (~20 degrees)
