HEAD_BONES=['Head','Jaw','Tongue','Nose','LipUpper','Ear.L','Ear.R','Eye.L','Eye.R','Whisker.L','Whisker.R','LidUpper.L','LidUpper.R','LidLower.L','LidLower.R','EarTip.L','EarTip.R','TongueMid','TongueTip']+list(FACE_BONES)
