# --- Round S look, ported into the generator (2026-10-10) -----------------------------------------------------------------
# codex's Round S (reviews/ROUND-S-CONTACT-REPAIR.md, scripts/blender/repair_lingxi_contacts.py) warped a BUILT .blend; the
# user liked the result, so the same two local warps now run here, on the final (posed-space) skin, every shape key and every
# strand root, so a build reproduces it. Paws: up to 8.5% narrower and 13% lower over the paw, its coat 35% shorter. Muzzle:
# the whisker pads 3.5 mm forward / 1.5 mm out, the philtrum's crease 1.5 mm back, the lower jaw's middle 6 mm fuller, the
# muzzle's coat 30% shorter. (Its re-posed clips are NOT ported - see HANDOFF Round U.)
def _paw_warp(p):
 q=p.copy();z=p[:,2]
 for sx in (-1,1):
  for pre in ('Front','Rear'):
   cx,cy,_=body_xf((sx*MPAW[pre]['x'],MPAW[pre]['c'][0],0)) if PAW_META else ((sx*.108,-.188,0) if pre=='Front' else (sx*.12,.2265,0))
   w=np.clip((.14-z)/.07,0,1)*np.exp(-((p[:,1]-cy)/.090)**6)*np.exp(-((p[:,0]-cx)/.105)**6)
   q[:,0]-=_v6('V6_PAW_NARROW',.085)*w*(p[:,0]-cx);q[:,2]-=_v6('V6_PAW_FLATTEN',.13)*w*np.maximum(0,z-.001)
 return q
def _muzzle_warp(p):
 q=p.copy();x,y,z=p.T;front=np.clip((-.375-y)/.035,0,1)
 lobes=np.exp(-((np.abs(x)-.034)/.026)**2-((z-.471)/.021)**2)*front;crease=np.exp(-(x/.006)**2-((z-.459)/.012)**2)*front
 q[:,1]-=_v6('V6_PAD_PUFF_MM',6.0)/1000*lobes-_v6('V6_CREASE_MM',3.0)/1000*crease   # round W: the pads 3.5 -> 6 mm, the crease 1.5 -> 3 mm: the shut mouth drawn by the pads' shadow (codex mouth-closed);q[:,0]+=.0015*np.sign(x)*lobes
 chin=np.exp(-(x/.055)**4-((z-.442)/.013)**2)*front;q[:,2]-=.006*chin
 return q
def _warp_mesh(ob,fn):
 for data in ([k.data for k in ob.data.shape_keys.key_blocks] if ob.data.shape_keys else [ob.data.vertices]):
  co=np.empty(len(data)*3,dtype='f');data.foreach_get('co',co);data.foreach_set('co',fn(co.reshape(-1,3).astype(float)).astype('f').ravel())
 ob.data.update()
if _v6('V6_ROUND_S_LOOK',1)>0:
 for ob in list(scene.objects):
  if ob.type!='MESH':continue
  if ob.name=='LX_Body' or ob.name.startswith(('LX_FrontPad','LX_FrontBean','LX_RearPad','LX_RearBean','LX_FrontClaw','LX_RearClaw')):_warp_mesh(ob,_paw_warp)
  elif ob.name=='LX_Head' or ob.name.startswith('LX_Lip'):_warp_mesh(ob,_muzzle_warp)
  elif ob.name.startswith('LX_Fur_'):
   P=int(ob.get('strand_points',NP));ishead=('Head' in ob.name or 'Lip' in ob.name or 'NoseVelvet' in ob.name);fn=_muzzle_warp if ishead else _paw_warp
   for data in ([k.data for k in ob.data.shape_keys.key_blocks] if ob.data.shape_keys else [ob.data.vertices]):
    co=np.empty(len(data)*3,dtype='f');data.foreach_get('co',co);co=co.reshape(-1,P,3).astype(float);root=co[:,0,:].copy();co+=(fn(root)-root)[:,None,:]
    if ishead:w=np.exp(-((np.abs(root[:,0])-.034)/.028)**2-((root[:,2]-.471)/.024)**2)*np.clip((-.375-root[:,1])/.035,0,1);k_=.30
    else:w=np.clip((.105-root[:,2])/.050,0,1)*(np.abs(root[:,0])>.04)*(np.abs(root[:,0])<.24);k_=.35
    co=co[:,:1,:]+(co-co[:,:1,:])*(1-k_*w[:,None,None]);data.foreach_set('co',co.astype('f').ravel())
   ob.data.update()
# Named actions with synchronized shape key actions. One timeline demonstrates all clips.
clips=[('Idle',72),('Walk',48),('Run',32),('Jump',48),('LieDown',48),('SideLie',48),('Sleep',72),('Curious',48),('Happy',48),('Yawn',60),('Lick',48),('Bite',48),('Knead',48),('Stretch',60),('PawPlay',48)]
if FACE_V1:clips+=[('Sit',48),('Loaf',60),('BellyUp',60),('ScratchEar',60),('WashFace',60),('GroomSide',60),('Turn',48)]   # rig v1: the block cat's sit / loaf / belly-up / scratch-ear / wash-face / groom-side / turn
eyelids=[o for o in eyelids if o.data.shape_keys];eye_shapes=[o for o in eye_shapes if o.data.shape_keys];claws=[o for o in claws if o.data.shape_keys];breathers=[o for o in breathers if o.data.shape_keys]
tongues=[tongue];shapeobs=eyelids+eye_shapes+claws+breathers+tongues;offset=1;manifest=[]
# --- Paw-lick solve -------------------------------------------------------------------------
# The lick pose used hand-set angles and the paw ended beside the face (it sits 10cm off the
# midline) - "misplaced". Here the rig's own rest matrices are chained by hand (the same
# parent-rest-basis product Blender evaluates) and a small search finds neck / head / leg
# angles that put the paw PAD in front of the mouth, facing it, with as little bending as
# possible. Solved once; the clip scales the angles by its ease-in / ease-out.
from mathutils import Matrix,Euler,Quaternion
def _half(r):return tuple(Quaternion().slerp(Euler(r,'XYZ').to_quaternion(),.5).to_euler('XYZ'))   # twice this is r, exactly
def _spread_rots(rots):
 """Round X: a pose given on the A joints (Loin, Spine, Neck, Tail0-4) -> half the turn on A and half on its B (SPLIT). Rotations
  that already name a B joint are taken as spread."""
 if not SPLIT or any(b in rots for b in SPLIT.values()):return rots
 r=dict(rots)
 for a,b in SPLIT.items():
  if a in r:r[a]=r[b]=_half(r[a])
 return r
def _spread(pb):
 for a,b in SPLIT.items():h=_half(tuple(pb[a].rotation_euler));pb[a].rotation_euler=h;pb[b].rotation_euler=h
def _fk(rots,locs=None):
 locs=locs or {};cache={}
 if 'Loin' not in rots and 'Spine' in rots:rots={**rots,'Loin':rots['Spine'],'Spine':(0,0,0)}   # round P: the solvers bend the back as one joint, at the loin - the pre-Loin rig exactly
 rots=_spread_rots(rots)
 def m(name):
  if name in cache:return cache[name]
  b=ad.bones[name];basis=Matrix.Translation(Vector(locs.get(name,(0,0,0))))@Euler(rots.get(name,(0,0,0)),'XYZ').to_matrix().to_4x4()
  r=(m(b.parent.name)@(b.parent.matrix_local.inverted()@b.matrix_local) if b.parent else b.matrix_local)@basis
  cache[name]=r;return r
 return m
def _tip(f,name):return f(name)@Vector((0,ad.bones[name].length,0))
def _search(cost,x0,lo,hi,samples,seed):
 """Random multi-start around x0, then shrinking coordinate descent. Deterministic."""
 r_=np.random.default_rng(seed);lo=np.asarray(lo,float);hi=np.asarray(hi,float)
 best=(cost(x0),np.asarray(x0,float))
 for v in lo+(hi-lo)*r_.random((samples,len(lo))):
  c_=cost(v)
  if c_<best[0]:best=(c_,v.copy())
 v=best[1];step=(hi-lo)/12
 for _ in range(90):
  improved=False
  for i in range(len(v)):
   for d in (-1,1):
    w=v.copy();w[i]=np.clip(w[i]+d*step[i],lo[i],hi[i]);cw=cost(w)
    if cw<best[0]:best=(cw,w);v=w;improved=True
  if not improved:step=step*.5
 return best
# --- Leg IK ------------------------------------------------------------------------------------
# Every clip now places FEET, and the legs are solved to reach them, instead of hand-set joint
# angles. That is what makes a planted paw stay planted, a knee bend forward and an elbow back.
# Each leg is a planar 2-bone chain (upper + lower) plus a paw whose angle is set directly; the
# plane is the leg's own rest plane, so the solve is done in rest space: the target is carried
# back through the parent's pose delta (spine, pelvis, shoulder blade, root roll) first.
def _ang(v):return math.atan2(v[2],v[1])
def _wrap(a):return (a+math.pi)%math.tau-math.pi
LEGS={}
for _s in 'LR':
 LEGS['F'+_s]=('Scap.'+_s,'FrontUpper.'+_s,'FrontLower.'+_s,'FrontPaw.'+_s,+1)   # elbow points back
 LEGS['H'+_s]=('Pelvis','RearUpper.'+_s,'RearLower.'+_s,'RearPaw.'+_s,-1)          # knee points forward
FOOT_OF={k:LEGS[k][3].replace('Paw.','Foot.') for k in LEGS} if FOOT else {}
LREST={}
for k,(par,up,lo,pw,bend) in LEGS.items():
 r={};chain_=(up,lo,pw)+((FOOT_OF[k],) if FOOT else ())
 for n in chain_:r[n]=_ang(Vector(ad.bones[n].tail_local)-Vector(ad.bones[n].head_local))
 sg={}
 for n in chain_:                       # which way a +X local rotation turns the bone in the plane
  f=_fk({n:(.1,0,0)});v=_tip(f,n)-f(n).translation;sg[n]=1.0 if _wrap(_ang(v)-r[n])>0 else -1.0
 LREST[k]=dict(ang=r,sign=sg,L1=ad.bones[up].length,L2=ad.bones[lo].length,foot=Vector(ad.bones[pw].head_local),x=ad.bones[up].head_local.x)
def leg_ik(rots,locs,key,target,paw_ang,abduct=False,foot_ang=None,paw_dir=None):
 """Solve one leg to put its wrist/hock at `target` (world) with the paw at world angle
  `paw_ang` in its plane. Returns (rotations, off-plane distance, over-reach).
  abduct (round R, WorkBuddy AUDIT-DEEP-QUANTIFIED #4): the solve was planar - a target off the leg's plane was simply
  missed by the off-plane distance, which the callers threw away and then swung the leg out of its plane by hand (add_*)
  with no re-solve, flinging lying paws 100 mm through the floor or up into the air. With abduct the leg first swings
  about the body's fore-aft axis through the hip / shoulder until the target IS in its plane, then solves in that plane."""
 par,up,lo,pw,bend=LEGS[key];R=LREST[key]
 f=_fk(rots,locs);D=f(par)@ad.bones[par].matrix_local.inverted()
 t=D.inverted()@Vector(target);h=Vector(ad.bones[up].head_local);phi=0.0
 if abduct:
  r=t-h;r.x-=R['x']-h.x;phi=math.atan2(r.x,-r.z);c_,s_=math.cos(phi),math.sin(phi)
  t=h+Vector((R['x']-h.x+r.x*c_+r.z*s_,r.y,-r.x*s_+r.z*c_))   # rotated about +Y by phi: now in the leg's plane
 if paw_dir is not None:
  # rig v1: the paw (metacarpus / metatarsus) along a WORLD direction - carried into the leg's swung plane like the target, so it holds
  # however far the leg is abducted (an angle in the vertical plane pointed the scratching toes in and down)
  pd=D.inverted().to_3x3()@Vector(paw_dir)
  if abduct:pd=Vector((pd.x*c_+pd.z*s_,pd.y,-pd.x*s_+pd.z*c_))
  paw_ang=_ang(pd)+_ang(D.to_3x3()@Vector((0,1,0)))
 d=Vector((0,t.y-h.y,t.z-h.z));L1,L2=R['L1'],R['L2']
 over=max(0,d.length-(L1+L2)*.995);dist=min(max(d.length,abs(L1-L2)+1e-3),(L1+L2)*.995)
 A=math.acos(max(-1,min(1,(L1*L1+dist*dist-L2*L2)/(2*L1*dist))))
 ua=_ang(d)+bend*A;knee=h+L1*Vector((0,math.cos(ua),math.sin(ua)))
 la=_ang(t-knee);pitch=_ang(D.to_3x3()@Vector((0,1,0)))
 du=_wrap(ua-R['ang'][up]);dl=_wrap(la-(R['ang'][lo]+du));dp=_wrap((paw_ang-pitch)-(R['ang'][pw]+du+dl))
 rv={up:(du*R['sign'][up],0,0),lo:(dl*R['sign'][lo],0,0),pw:(dp*R['sign'][pw],0,0)}
 if FOOT:   # round X2: the Foot at world angle foot_ang in the leg's plane; None = rigid on the Paw (the old one-piece paw)
  ft=FOOT_OF[key];rv[ft]=(0,0,0) if foot_ang is None else (_wrap((foot_ang-pitch)-(R['ang'][ft]+du+dl+dp))*R['sign'][ft],0,0)
 if abs(phi)>1e-6:   # the plane swing (-phi about the rest Y axis through the joint), composed onto the upper bone's flexion
  A=ad.bones[up].matrix_local.to_3x3().inverted()@Vector((0,1,0))
  rv[up]=tuple((Quaternion(A,-phi).to_matrix()@Euler(rv[up],'XYZ').to_matrix()).to_euler('XYZ'))
