# Sleep was SideLie with the lids shut (root, roll, back line and length all within 0.5 mm of it). A sleeping cat
# curls up: on the same flank, the back bent (Spine/Neck/Head flexed, which on its side is a C on the floor), the
# hind legs drawn forward, the forepaws tucked, the tail wrapped round the rump, the nose down by the paws. The
# pelvis's pitch (yaw) turns the curl on the floor so the pose camera sees the closed eyes and the C, not the crown,
# and the head turns back up off its cheek a little (head_roll), chin on the paws.
# Round Q (codex lingxi-ref-pose-sleep-app.png): the face turned back up toward the camera (head_roll -.6 -> -1.4, neck_side .2 -> -.25,
# head_side .2 -> -.1) - curled with the face rolled down, the camera saw the crown and the back of the ears (round-q-test z1/z2).
# Round V (codex lingxi-ref-pose-sleep-app.png: a ring - back round the outside, face in it looking out, tail across the front): the
# back curls 1.4 (was .8) and the neck .9, the hind legs tuck in under the belly, the tail sweeps round the front, and the face is
# set upright toward the camera in the world (_face_world) rather than left at the end of the curl (round-v-test q1-q8).
# Round X: the back curls 2.2 (was 1.4) and the neck 1.1 (.9), now over the split back's four joints - a closed ring, as codex's
# lingxi-ref-pose-sleep-top.png; the tail is laid round the ring's gap to the chin by _tail_wrap (its per-joint angles here are overridden).
# Round ZV (final check: the tail never reached the chin - V6_TAIL_DEBUG: a 974 mm path round a 139 deg gap for a 474 mm tail; the ring was
# too open): the back curls 2.2 -> 3.0 (gap 115 deg; 3.4 threw the paws out) and the tail lies closer (V6_SP_TAIL_GAP 2 mm)
# Round ZZG (codex ROUND-ZZF-AUDIT #3, tail ring): `yaw` turns the PELVIS, but the legs are placed from the root, so turning it threw the
# upper hind paw up onto the back (259 -> 381 mm at -3.1). `turn` turns the WHOLE curl on the floor (the root, world up) so that the ring's
# gap - where the tail crosses from the rump to under the chin - faces the camera, as codex's sleep-app / -top. Measured (round-zzg-test):
# turn 0 -> -1.45 shortens the tail's path 786 -> ~480 mm (tail 474) - it now crosses the front instead of stopping beside the head.
# paws: the forepaws under the chin (codex: the chin rests on them, the tail in front), the upper one stacked on the lower (from its shoulder
