K_LOW='HL' if SIDELOUNGE['hip_roll']>=0 else 'HR'   # hips rolled +: the LEFT hind leg is underneath (round ZZW: rolled - for the mirrored lounge, the right)
# Round P: a lying pose's back bend is shared between the loin and the thoracic joint (_back; 0 = all at the loin, the
# old one-hinge back, .5 = an even curve). The other clips keep their solved / tuned single bend.
BACK_CURVE={'LieDown':_v6('V6_BACK_LD',.5),'SideLie':_v6('V6_BACK_SL',.5),'Sleep':_v6('V6_BACK_SP',.5)}
def _back(pb,name):
 a=BACK_CURVE.get(name,0.0);r=Vector(pb['Spine'].rotation_euler)
 pb['Loin'].rotation_euler=r*(1-a);pb['Spine'].rotation_euler=r*a
# Round P: lying down took a linear third of the clip and stopped dead - every part arriving on the same frame. Now it
# eases in and out over LIE_T, and the neck / head and the tail settle a beat after the body (_settle(u,t0,t1)).
LIE_T=_v6('V6_LIE_T',.40)
def _settle(u,t0=0.0,t1=None):
 e=min(1,max(0,(u-t0)/((LIE_T if t1 is None else t1)-t0)));return e*e*(3-2*e)
# Round U (codex Round S found it: R's SideLie sank 41 mm through the floor at frame 259, mid lie-down - the held frames were
# calibrated, the transition was not): while a lying clip moves, the trunk's real skin is kept off the floor - a sample of the
# body's trunk vertices, skinned with their own weights, and the whole body lifted by any shortfall before the legs solve.
_TRUNK=None
def _trunk_sample():
 global _TRUNK
 if _TRUNK is None:
  me=body.data;gn={g.index:g.name for g in body.vertex_groups};trunk=('Root','Pelvis','Loin','Spine','Neck','Head','LoinB','Chest','NeckB')+(('RearUpper.L','RearUpper.R') if FACE_V1 else ())   # rig v1: the thigh's flesh rides the femur now - a sitting haunch went 8 mm under unseen
  idx=[];W={}
  for vi in range(0,len(me.vertices),max(1,len(me.vertices)//6000)):
   v=me.vertices[vi]
   ws={gn[g.group]:g.weight for g in v.groups if g.weight>1e-4 and gn[g.group] in ad.bones}
   if ws and sum(w for n,w in ws.items() if n in trunk)>.7*sum(ws.values()):idx.append((v.co[:],ws))
  co=np.array([c for c,_ in idx]);names=sorted({n for _,ws in idx for n in ws})
  W={n:np.array([ws.get(n,0) for _,ws in idx]) for n in names};tot=sum(W.values());W={n:w/np.maximum(tot,1e-9) for n,w in W.items()}
  _TRUNK=(co,W)
 return _TRUNK
def _lift_off_floor(pb,margin=.002):
 co,W=_trunk_sample();rots={b.name:tuple(pb[b.name].rotation_euler) for b in ad.bones};f=_fk(rots,{'Root':tuple(pb['Root'].location)})
 z=np.zeros(len(co))
 for n,w in W.items():M=np.array(f(n)@ad.bones[n].matrix_local.inverted());z+=w*(co@M[2,:3]+M[2,3])
 low=float(z.min())
 if low<margin:pb['Root'].location.y+=margin-low
_PAWS={}
def _paw_sample(k):
 """The skin of one leg's paw (body vertices mostly on its Paw / Toe bones), with their weights - for keeping the real paw
  surface, not its bone, above the floor (round U)."""
 if k not in _PAWS:
  me=body.data;gn={g.index:g.name for g in body.vertex_groups};pw=LEGS[k][3];suf=pw[-1];pre=pw[:-6]
  own={pw}|{pre+f'Toe{i}.'+suf for i in range(4)}|({FOOT_OF[k]} if FOOT else set());rows=[]
  for vi in range(0,len(me.vertices),1):   # Z4: every vertex (every 3rd missed the hind heel's lowest, -2.3 mm in the lick)
   v=me.vertices[vi];ws={gn[g.group]:g.weight for g in v.groups if g.weight>1e-4 and gn[g.group] in ad.bones}
   if ws and sum(w for n,w in ws.items() if n in own)>.5*sum(ws.values()):rows.append((v.co[:],ws))
  for nm_ in [f'LX_{pre}Pad.{suf}']+[f'LX_{pre}Bean{i}.{suf}' for i in range(4)]:   # Z4: the pad and toe beans too (PawPlay's -4.4 mm were beans)
   ob_=bpy.data.objects.get(nm_)
   if not ob_:continue
   gb={g.index:g.name for g in ob_.vertex_groups}
   for v in ob_.data.vertices:
    ws={gb[g.group]:g.weight for g in v.groups if g.weight>1e-4 and gb[g.group] in ad.bones}
    if ws:rows.append(((ob_.matrix_world@v.co)[:],ws))
  co=np.array([c for c,_ in rows]);names=sorted({n for _,ws in rows for n in ws})
  W={n:np.array([ws.get(n,0) for _,ws in rows]) for n in names};tot=sum(W.values());_PAWS[k]=(co,{n:w/np.maximum(tot,1e-9) for n,w in W.items()})
 return _PAWS[k]
def _paw_low(k,rots,locs):
 co,W=_paw_sample(k);f=_fk(rots,locs);z=np.zeros(len(co))
 for n,w in W.items():M=np.array(f(n)@ad.bones[n].matrix_local.inverted());z+=w*(co@M[2,:3]+M[2,3])
 return float(z.min())
# Round V: the lick's paw by a SPATIAL arm solve with the paw's full orientation - ported from codex's Round S post-pass
# (repair_lingxi_contacts.py), into the generator. The planar leg solve can turn the paw only in the leg's plane, so the pad
# could never face a tongue on the midline: the solve bowed the head onto a paw held at the chest instead. Here the shoulder
# blade comes forward and down, the forearm reaches the mouth, and the pad turns square to the tongue's tip, toes up; then the
# pad's centre is walked onto a point 3 mm in front of the tip. All of it eases in / out with the clip's hold.
def _set_world_rot(n,R,rots,locs):
 b=ad.bones[n];f=_fk(rots,locs);base=(f(b.parent.name)@(b.parent.matrix_local.inverted()@b.matrix_local)) if b.parent else b.matrix_local
 rots[n]=tuple((base.to_3x3().inverted()@R).to_euler('XYZ'))
def _arm_solve(up,lo,pw,target,orient,rots,locs,turn=None):
 f=_fk(rots,locs);h=f(up).translation;d=Vector(target)-h;L1,L2=ad.bones[up].length,ad.bones[lo].length
 dist=min(max(d.length,abs(L1-L2)+.0005),L1+L2-.0005);v=d.normalized();elbow=f(lo).translation-h;pole=elbow-v*elbow.dot(v)
 if pole.length<1e-5:pole=v.cross(Vector((1,0,0)))
 pole.normalize();a=(L1*L1-L2*L2+dist*dist)/(2*dist);b=math.sqrt(max(0,L1*L1-a*a));knee=h+v*a+pole*b;end=h+v*dist
 for n,dr in ((up,knee-h),(lo,end-knee)):
  f=_fk(rots,locs);base=f(n).to_3x3();_set_world_rot(n,(base@Vector((0,1,0))).rotation_difference(dr.normalized()).to_matrix()@base,rots,locs)
 # the paw turns only part of the way from where the forearm carries it to the full pad-to-tongue orientation: all the way,
 # the wrist's twist collapsed the paw skin into a stretched sock (linear skinning, round-v-test l3/l4)
 f=_fk(rots,locs);nat=(f(lo)@(ad.bones[lo].matrix_local.inverted()@ad.bones[pw].matrix_local)).to_3x3()
 _set_world_rot(pw,nat.to_quaternion().slerp(Matrix(orient).to_quaternion(),_v6('V6_LICK_PAW_TURN',.85 if FACE_V1 else .55) if turn is None else turn).to_matrix(),rots,locs)
def _forearm_twist(pb):
 """Rig v1: each forearm twist bone takes half the paw's turn about the forearm's axis (swing-twist of the paw's local rotation)."""
 if not FACE_V1:return
 for sf in 'LR':
  pw=pb['FrontPaw.'+sf];q=pw.rotation_euler.to_quaternion()
  ax=(ad.bones['FrontPaw.'+sf].matrix_local.to_3x3().inverted()@ad.bones['FrontLower.'+sf].matrix_local.to_3x3()@Vector((0,1,0))).normalized()
  d=Vector((q.x,q.y,q.z)).dot(ax);tw=2*math.atan2(d,q.w);tw=_wrap(tw)
  pb['ForearmTwist.'+sf].rotation_euler=(0,.5*tw,0)
_PADL=None
def _lick_reach(pb,hold):
 global _PADL
 if hold<1e-3:return   # not lifting yet: leave the planar solve's leg exactly as it is
 up,lo,pw='FrontUpper.R','FrontLower.R','FrontPaw.R'
 if _PADL is None:
  P=np.array([v.co[:] for v in bpy.data.objects['LX_FrontPad.R'].data.vertices]).mean(0);_PADL=ad.bones[pw].matrix_local.inverted()@Vector(P)
 names=[b.name for b in ad.bones];rots={n:tuple(pb[n].rotation_euler) for n in names};locs={n:tuple(pb[n].location) for n in names}
 f=_fk(rots,locs);H=f('Head');tip=H@lick_l;tdir=(H.to_3x3()@lick_d).normalized();goal=tip+tdir*_v6('V6_LICK_PAD_GAP',.003)
 orig=f(pw).translation.copy();origR=f(pw).to_3x3()
 # the pad square to the tongue (sole normal = -tongue direction), the toes as near straight up as that allows
 Rr=ad.bones[pw].matrix_local.to_3x3();n0=Vector((0,0,-1));a0=(Rr@Vector((0,1,0)));a0=(a0-n0*a0.dot(n0)).normalized()
 n1=-tdir;a1=Vector((0,0,1))-n1*n1.z;a1=a1.normalized() if a1.length>1e-4 else Vector((0,1,0))
 F0=Matrix((a0,n0,a0.cross(n0))).transposed();F1=Matrix((a1,n1,a1.cross(n1))).transposed();orient=F1@F0.transposed()@Rr
 b=ad.bones['Scap.R'];base=(f(b.parent.name)@(b.parent.matrix_local.inverted()@b.matrix_local)).to_3x3()
 locs['Scap.R']=tuple(base.inverted()@Vector((0,-_v6('V6_LICK_SCAP_FWD',.065)*hold,-_v6('V6_LICK_SCAP_DN',.020)*hold)))
 target=orig.copy()
 for _ in range(10):
  _arm_solve(up,lo,pw,target,orient,rots,locs);pad=_fk(rots,locs)(pw)@_PADL;sh=goal-pad
  if sh.length<.0008:break
  target+=sh
 _arm_solve(up,lo,pw,orig.lerp(target,hold),origR.to_quaternion().slerp(orient.to_quaternion(),hold).to_matrix(),rots,locs)
 for n in (up,lo,pw):pb[n].rotation_euler=rots[n]
 if hold>.99 and _v6('V6_LICK_DEBUG',0)>0:
  f=_fk(rots,locs);print('LICK_REACH',json.dumps({'pad_goal_mm':round(1000*(f(pw)@_PADL-goal).length,1),'shoulder_goal_mm':round(1000*(f(up).translation-goal).length,1),
   'arm_mm':round(1000*(ad.bones[up].length+ad.bones[lo].length),1),'goal':[round(1000*c) for c in goal],'pad':[round(1000*c) for c in f(pw)@_PADL]}))
 pb['Scap.R'].location=locs['Scap.R']
def _face_world(pb,yaw,pitch,roll,k=1.0):
 """Round V: set the head's WORLD orientation - the standing face turned by yaw (about up), pitched (+ = nose down) and
  tilted (about the view axis) - blended in by k over what the neck chain gave it. Curled up, the head's orientation was
  the sum of every bend down the back and the face ended up turned away from the camera (round-v-test q4-q6)."""
 names=[b.name for b in ad.bones];rots={n:tuple(pb[n].rotation_euler) for n in names};locs={n:tuple(pb[n].location) for n in names}
 f=_fk(rots,locs);cur=f('Head').to_3x3()
 want=Matrix.Rotation(yaw,3,'Z')@Matrix.Rotation(pitch,3,'X')@Matrix.Rotation(roll,3,'Y')@ad.bones['Head'].matrix_local.to_3x3()
 _set_world_rot('Head',cur.to_quaternion().slerp(want.to_quaternion(),k).to_matrix(),rots,locs);pb['Head'].rotation_euler=rots['Head']
# Round X: the tail laid along a path in the WORLD - on the floor, round the outside of the body, from behind the rump to a chosen end
# (LieDown: beside the forepaw on one side; Sleep: across the front of the face). Per-joint angles could not do it: each joint turns
# about axes the droop / the roll before it has already tipped, so the same numbers sent the tail under the belly, up into the air or
# back round the rump (round-v-test s1-s6). Each bone in turn points at the path point one bone-length on from its head.
TAIL_CHAIN=None
def _tail_chain():
 global TAIL_CHAIN
 if TAIL_CHAIN is None:
  c=['Tail0'];kids={b.parent.name:b.name for b in ad.bones if b.name.startswith('Tail') and b.parent}
  while c[-1] in kids:c.append(kids[c[-1]])
  TAIL_CHAIN=c
 return TAIL_CHAIN
_HEADS=None
def _tail_wrap(pb,via,end,k=1.0,margin=None,lead=0.0,shortest=False):
 """via: a floor direction (x,y) the path passes on its way round, or None - through the gap between the tail's root and `end` (a curled
  cat closes its ring with its tail); end: the world point (x,y) it ends beside; lead: the path leaves the rump this far (rad) round
  toward its way, so the tail drops to the floor on the diagonal instead of spending its length straight behind.
  shortest keeps a changing endpoint from flipping the sweep across a full turn during SideLie entry."""
 global _HEADS
 if k<1e-3:return
 margin=_v6('V6_TAIL_WRAP_GAP',.012) if margin is None else margin
 names=[b.name for b in ad.bones];rots={n:tuple(pb[n].rotation_euler) for n in names};locs={n:tuple(pb[n].location) for n in names};f=_fk(rots,locs)
 pts=[]
 co,W=_trunk_sample();P=np.zeros((len(co),3))
