def _ease(u,a=.2,b=.2):h=min(1,u/a,(1-u)/b);return h*h*(3-2*h)
# scratch-ear (round-v-test f2-f7): the head swings down and over to the LEFT side (+ here) and tilts up, the trunk stays upright - a
# pelvis roll laid the whole cat on its side (the pelvis is the trunk's root), the head bent forward-down left the ear 480 mm from the hip
# Round ZZG (codex ROUND-ZZF-AUDIT #2, measured with round-zzg-test/sem.py at frame 975): the forepaws hung 16.6 / 44.9 mm (bent over to
# the left the chest rode up on the right). fore_down presses each to the floor (a bisected drop, scapula following, the leg free to swing
# out: L 1.4 mm); chest_twist -.35 levels the shoulders so the right one reaches too (R 1.5 mm; -.25: 11.2, +.25 worse). Pelvis side-roll
# .037 rad, hind foot to ear base 11 mm, head 456 -> 445 mm (codex: <= .10, <= 25, <= 20 lower) - all in.
SE={k:_v6('V6_SE_'+k.upper(),d) for k,d in dict(spine_side=.40,hip_roll=.10,neck=.10,neck_side=.40,head=-.35,head_roll=.25,foot_dy=.02,foot_dz=-.02,foot_pa=.6,fore_down=1.0,chest_twist=-.35).items()}
# Round ZZZ3 (user list: 「舔侧身改成坐直了回头舔」): the neck up (.30 -> -.10) and the face near level (fpitch .90 -> .55) sit it up; the chest twists
# round (.35 -> .70) and the neck bends over (.55 -> .75) to bring the flank to the mouth, the face turned less (fyaw 1.45 -> 1.30: more turn
# pushed the nose 57-61 mm off, 1.0 44 mm) - nose 4.0 mm off the flank, 84 mm higher than the hunched lick.
GS={k:_v6('V6_GS_'+k.upper(),d) for k,d in dict(spine_side=.55,twist=.70,neck=-.10,neck_side=.75,head=.25,head_yaw=.65,face=1.0,fyaw=1.30,fpitch=.55,froll=0.0,turn=-.70).items()}   # groom-side; turn (round ZZX, codex STAGE-ZZQ-AUDIT #5: the front camera saw only the crown): the whole seated cat yawed
# about the root (legs, face and tail with it) so the licked flank faces the camera - an eye and the nose show, the nose still 2.4 mm off the flank
# (+.7 turned the face away; turning the face itself back, fyaw .95, left the nose 65 mm off the flank). Blink .5 -> .15 opens that eye.
WF={k:_v6('V6_WF_'+k.upper(),d) for k,d in dict(head_roll=.25,head=.12,turn=.85).items()}   # wash-face
# Round ZZX (codex wave research #4, against codex lingxi-ref-ourcam-belly-up - the belly-up redrawn on the front camera): rolled LESS, 2.7 -> 2.20,
# turns the white belly to the low camera (nearer pi it faces the ceiling); twist -.45 -> -.25, spine .25 -> .35, paws up a little (f_dz .16, h_dz .17),
# wiggle .07. Rolling over the legs before they folded put the under shin 5-11 mm through the floor mid-roll: they tuck first (V6_BU_LEG_T .15).
BU={k:_v6('V6_BU_'+k.upper(),d) for k,d in dict(roll=2.20,turn=-1.3,twist=-.25,spine=.35,neck=.15,wiggle=.07,face_pitch=.15,face_roll=-.35,f_dy=.03,f_dz=.16,f_pa=1.2,h_dy=-.06,h_dz=.17,h_pa=.8).items()}   # belly-up
LF={k:_v6('V6_LF_'+k.upper(),d) for k,d in dict(dx=-.015,dy=.03,z=.050,pa=-20,fpa=.35).items()}   # loaf: forepaws folded under the chest
TURN=_v6('V6_TURN',math.pi/2);TURN_STEPS={'FL':(.08,.34),'HR':(.24,.50),'FR':(.42,.68),'HL':(.58,.84)}
