def place_legs(name,u,pb,hold=0.0):
 """Solve all four legs for this frame, after the body (root, spine, head) is posed."""
 names=['Root','Pelvis','Loin','Spine','Neck','Head','Scap.L','Scap.R']+list(SPLIT.values())
 rots={n:tuple(pb[n].rotation_euler) for n in names};locs={'Root':tuple(pb['Root'].location)}
 f=_fk(rots,locs);RD=_root_delta(f)
 # Lying (sphinx): forearms flat on the ground ahead of the shoulders; hocks down behind the hips,
 # the hind feet flat forward. Targets are for a body lowered 11cm, in the body's own frame.
 lie={}
 for k in LEGS:
  hy=ad.bones[LEGS[k][1]].head_local.y
  # .045 was the folded ankle's height, and it put the folded paw 63 mm BELOW the floor
  # (v6_ground_calib.py). Raise the target rather than the root: the silhouette still has
  # to lose its height when the cat lies down.
  L=LIEDOWN;lie[k]=(Vector((LREST[k]['x'],hy-L['f_dy'],L['f_z']+L['drop'])),math.radians(L['f_pa'])) if k[0]=='F' else (Vector((LREST[k]['x']+math.copysign(L['h_dx'],LREST[k]['x']),hy+L['h_dy'],L['h_z']+L['drop'])),math.radians(L['h_pa']))
 placed={}   # round R: the world targets already given out this frame (the upper hind paw lies on the under one)
 for k in (sorted(LEGS,key=lambda k:k!=K_LOW) if name=='SideLie' else LEGS):   # round ZZW: the under hind leg first, whichever side it is
  foot=LREST[k]['foot'].copy();pa=_paw_rest(k);tg=foot;fa=None;pdir=None
  if name in ('Walk','Run'):
   g=WALK if name=='Walk' else RUN;dy,dz,flex=_gait(g,u,k)
   if k[0]=='H':dz*=1.25   # the hind paw clears its longer swing a little higher (round J: no stride multiplier - the planted paws must all move at the body's speed)
   tg=foot+Vector((0,dy-ROOT_TRAVEL(g)*u,dz))   # the ground under a travelling body: a planted paw's target stays fixed in the world
  elif name=='Jump' and JUMP_PHASED:
   off_,on_=(JUMP_T[0],JUMP_T[2]) if k[0]=='F' else (JUMP_T[1],JUMP_T[3])
   push=0.0;base=foot;flat=0.0
   if k[0]=='H' and .20<=u<on_:
    # the hind feet push off: the metatarsus tips up .6 rad - round X2 (codex lingxi-ref-hindfoot-pushoff-closeup.png): on its toes,
    # the knuckle (MTP) held on the floor and the foot flat, so the hock rises and the leg pushes out longer (was the whole paw
    # tipping onto its front edge round the hock)
    push=.6*((min(u,off_)-.20)/(off_-.20))**2
    if FOOT:mtp=Vector(ad.bones[FOOT_OF[k]].head_local);Lp=ad.bones[LEGS[k][3]].length;base=mtp-Lp*Vector((0,math.cos(pa+push),math.sin(pa+push)));flat=1.0
   _land=Vector((0,-_jump_fwd(on_),0))   # round ZZZ+1: the paws come down where the body has carried them
   if u>(off_+on_)/2:base=base+_land
   if off_<u<on_:
    keys=JUMP_LEGS[k[0]];bn='Chest' if k[0]=='F' else 'Pelvis';D=f(bn)@ad.bones[bn].matrix_local.inverted()
    tb=D@(foot+Vector((0,_jump_key(u,[(c[0],c[1]) for c in keys]),_jump_key(u,[(c[0],c[2]) for c in keys]))))
    w_=min(1,(u-off_)/.05,(on_-u)/.05);w_=w_*w_*(3-2*w_)   # into / out of the floor mark
    tg=base.lerp(tb,w_);tg.z=max(tg.z,0.0)
    if _v6('V6_JUMP_PLANT',1)>0:
     # Round Z4 (codex CAT-REALISM-GAP P0, jump sole slip 7.2 mm): over the floor the paw still slid toward its mark - one blend for
     # height and position, and the height reaches the floor first (v6_stance_probe: the planted pad moved 8.9 mm in a frame at
     # touch-down). Across the floor it now arrives .02 (~1 frame) before it lands and leaves .02 after it lifts: lands straight down.
     # ...and by height: the nose-down trunk brings the forepaws to the floor ~.05 early, so across the last 3 cm of their drop
     # (above their own floor height) they close on the mark as well
     wh=min(1,max(0,(u-off_-.02)/.05),max(0,(on_-u-.02)/.05));wz=min(1,max(0,(base.lerp(tb,w_).z-base.z)/.03))
     wh=min(wh*wh*(3-2*wh),wz*wz*(3-2*wz));th=base.lerp(tb,wh);tg.x,tg.y=th.x,th.y
     wa=wh   # the paw's angle as well: turning flat on the floor it pivoted on its bone and the planted pad slid 6.8 mm in a frame
    else:wa=w_
    tg.z=max(tg.z,base.z*(1-wa))   # Z4: a paw turned flat stops at its own standing height (z 0 is the bone, 48 mm under it: -9.5 mm at frame 187)
    pa+=push*(1-wa)+_jump_key(u,[(c[0],c[3]) for c in keys])*wa+_ang(D.to_3x3()@Vector((0,1,0)))*wa;flat*=1-wa
   elif u<=off_:
    tg=base;pa+=push
   else:tg=base   # landed: on the moved mark
   if FOOT and flat>0:R_=LREST[k]['ang'];ft=FOOT_OF[k];rig_=pa+(R_[ft]-R_[LEGS[k][3]]);fa=rig_+_wrap(R_[ft]-rig_)*flat
  elif name=='Jump':
   lift=math.sin(math.pi*u)**2
   tg=foot+(Vector((0,-.09*lift,.30*lift)) if k[0]=='F' else Vector((0,.11*lift,.27*lift)));pa+=lift*(.9 if k[0]=='F' else 1.2)
  elif name in ('LieDown','SideLie','Sleep'):
   fr=1.0 if name=='Sleep' else _settle(u);lt,la=lie[k];D_=RD
   if name=='SideLie' and SL_MODE==2:
    # the forearms as in LieDown, from the (yawed) root; the hind legs folded in the PELVIS's plane, which the hip roll lays down
    K=SIDELOUNGE
    if k[0]=='F':lt,la=Vector((math.copysign(K['f_half'],LREST[k]['x']) if K['f_half']>0 else LREST[k]['x'],ad.bones[LEGS[k][1]].head_local.y-K['f_dy'],K['f_z']+K['drop'])),math.radians(K['f_pa']);D_=RD   # round ZZG: f_half - the forepaws side by side (codex ZZF #4: centres 45-70 mm apart; they were 216)
    else:lt,la=foot+Vector((0,K['h_dy'],K['h_dz'])),pa+K['h_pa'];D_=f('Pelvis')@ad.bones['Pelvis'].matrix_local.inverted()
    tg=D_@(foot.lerp(lt,fr));pa=pa+(la-pa)*fr
    if k[0]=='H':pa=pa+_ang(D_.to_3x3()@Vector((0,1,0)))
